def f(a: int, b: int) -> int:
    """Returns the difference between a and b if they have opposite signs, otherwise returns their sum. If either is zero, returns zero."""
    if a == 0 or b == 0:
        return 0
    if (a < 0 and b > 0) or (a > 0 and b < 0):
        return -(a + b)
    else:
        return a + b

